import { readFileSync } from "node:fs";
import type { GatheredInfoCategory } from "./submission-template-types";
import type {
  CheckpointCriterion,
  CheckpointTemplate,
  CheckpointType,
} from "./checkpoint-template-types";
import { isCheckpointType } from "./checkpoint-template-types";

const VALID_SOURCES: readonly string[] = [
  "keywords",
  "competitors",
  "redhatProducts",
  "externalPeople",
  "internalPeople",
  "externalPriorArt",
  "internalPriorArt",
  "marketIntelligence",
  "problemStatements",
  "targetAudiences",
  "solutionApproaches",
  "constraints",
  "openQuestions",
];

function validateSources(
  sources: unknown[],
  context: string,
): GatheredInfoCategory[] {
  const result: GatheredInfoCategory[] = [];
  for (const source of sources) {
    if (typeof source !== "string" || !VALID_SOURCES.includes(source)) {
      throw new Error(context + ' has invalid source "' + String(source) + '"');
    }
    result.push(source as GatheredInfoCategory);
  }
  return result;
}

function validateCriterion(
  entry: Record<string, unknown>,
  checkpointId: string,
  index: number,
): CheckpointCriterion {
  const id = entry["id"];
  if (!id || typeof id !== "string") {
    throw new Error(
      "Criterion at index " +
        String(index) +
        ' in checkpoint "' +
        checkpointId +
        '" is missing required field "id"',
    );
  }

  const label = entry["label"];
  if (!label || typeof label !== "string") {
    throw new Error(
      'Criterion "' +
        id +
        '" in checkpoint "' +
        checkpointId +
        '" is missing required field "label"',
    );
  }

  const description = entry["description"];
  if (!description || typeof description !== "string") {
    throw new Error(
      'Criterion "' +
        id +
        '" in checkpoint "' +
        checkpointId +
        '" is missing required field "description"',
    );
  }

  const result: CheckpointCriterion = { id, label, description };

  if (entry["sources"] && Array.isArray(entry["sources"])) {
    result.sources = validateSources(
      entry["sources"],
      'Criterion "' + id + '" in checkpoint "' + checkpointId + '"',
    );
  }

  return result;
}

function validateCheckpoint(
  entry: Record<string, unknown>,
  index: number,
): CheckpointTemplate {
  const id = entry["id"];
  if (!id || typeof id !== "string") {
    throw new Error(
      "Checkpoint at index " +
        String(index) +
        ' is missing required field "id"',
    );
  }

  const type = entry["type"];
  if (!type || typeof type !== "string") {
    throw new Error(
      'Checkpoint "' + id + '" is missing required field "type"',
    );
  }
  if (!isCheckpointType(type)) {
    throw new Error(
      'Checkpoint "' +
        id +
        '" has invalid type "' +
        type +
        '". Must be "definition-of-ready" or "definition-of-done"',
    );
  }

  const label = entry["label"];
  if (!label || typeof label !== "string") {
    throw new Error(
      'Checkpoint "' + id + '" is missing required field "label"',
    );
  }

  const criteriaRaw = entry["criteria"];
  if (!Array.isArray(criteriaRaw) || criteriaRaw.length === 0) {
    throw new Error(
      'Checkpoint "' +
        id +
        '" is missing required field "criteria" (must be a non-empty array)',
    );
  }

  const criteria: CheckpointCriterion[] = [];
  const seenCriterionIds = new Set<string>();
  for (let i = 0; i < criteriaRaw.length; i++) {
    const criterion = validateCriterion(
      criteriaRaw[i] as Record<string, unknown>,
      id,
      i,
    );
    if (seenCriterionIds.has(criterion.id)) {
      throw new Error(
        'Duplicate criterion ID "' +
          criterion.id +
          '" in checkpoint "' +
          id +
          '"',
      );
    }
    seenCriterionIds.add(criterion.id);
    criteria.push(criterion);
  }

  const result: CheckpointTemplate = {
    id,
    type: type as CheckpointType,
    label,
    criteria,
  };

  if (entry["description"] && typeof entry["description"] === "string") {
    result.description = entry["description"];
  }

  return result;
}

export function parseCheckpointTemplates(
  yamlString: string,
): CheckpointTemplate[] {
  const raw: unknown = load(yamlString);

  if (typeof raw !== "object" || raw === null) {
    throw new Error("Checkpoint template YAML must be a valid object");
  }

  const doc = raw as Record<string, unknown>;

  if (!Array.isArray(doc["checkpoints"])) {
    throw new Error(
      'Checkpoint template YAML must contain a top-level "checkpoints" array',
    );
  }

  const checkpointsRaw = doc["checkpoints"] as unknown[];
  const checkpoints: CheckpointTemplate[] = [];
  const seenIds = new Set<string>();

  for (let i = 0; i < checkpointsRaw.length; i++) {
    const checkpoint = validateCheckpoint(
      checkpointsRaw[i] as Record<string, unknown>,
      i,
    );
    if (seenIds.has(checkpoint.id)) {
      throw new Error(
        'Duplicate checkpoint ID "' +
          checkpoint.id +
          '" in checkpoint template',
      );
    }
    seenIds.add(checkpoint.id);
    checkpoints.push(checkpoint);
  }

  return checkpoints;
}

export function loadCheckpointTemplates(
  templatePath?: string,
): CheckpointTemplate[] {
  const path = templatePath || process.env.CHECKPOINT_TEMPLATE_PATH;
  if (!path) {
    throw new Error(
      "No checkpoint template path provided. " +
        "Set CHECKPOINT_TEMPLATE_PATH env var or pass templatePath argument.",
    );
  }
  const yamlString = readFileSync(path, "utf-8");
  return parseCheckpointTemplates(yamlString);
}

export function getCheckpointsByType(
  templates: CheckpointTemplate[],
  type: CheckpointType,
): CheckpointTemplate[] {
  return templates.filter((t) => t.type === type);
}

export function getCheckpointById(
  templates: CheckpointTemplate[],
  id: string,
): CheckpointTemplate | undefined {
  return templates.find((t) => t.id === id);
}
"}

