  id: string;
  label: string;
  description: string;
  sources?: string[];
}

export interface PartialCheckpoint {
  id: string;
  type: string;
  label: string;
  description?: string;
  criteria: PartialCriterion[];
}

export function buildCheckpointTemplateYaml(
  checkpoints: PartialCheckpoint[],
): string {
  if (checkpoints.length === 0) {
    return "checkpoints: []\n";
  }
  const lines: string[] = ["checkpoints:"];
  for (const cp of checkpoints) {
    lines.push(`  - id: ${cp.id}`);
    lines.push(`    type: ${cp.type}`);
    lines.push(`    label: "${cp.label}"`);
    if (cp.description) {
      lines.push(`    description: "${cp.description}"`);
    }
    if (cp.criteria.length === 0) {
      lines.push("    criteria: []");
    } else {
      lines.push("    criteria:");
      for (const cr of cp.criteria) {
        lines.push(`      - id: ${cr.id}`);
        lines.push(`        label: "${cr.label}"`);
        lines.push(`        description: "${cr.description}"`);
        if (cr.sources && cr.sources.length > 0) {
          lines.push("        sources:");
          for (const src of cr.sources) {
            lines.push(`          - ${src}`);
          }
        }
      }
    }
  }
  return lines.join("\n") + "\n";
}

export function buildMinimalCheckpoint(
  overrides?: Partial<PartialCheckpoint>,
): PartialCheckpoint {
  return {
    id: "test-checkpoint",
    type: "definition-of-ready",
    label: "Test Checkpoint",
    criteria: [
      {
        id: "test-criterion",
        label: "Test Criterion",
        description: "A test criterion",
      },
    ],
    ...overrides,
  };
}
