      label: '"Test Checkpoint"',
    };

    const lines: string[] = ["checkpoints:", "  - "];
    let first = true;
    for (const [key, value] of Object.entries(allFields)) {
      if (key === field) continue;
      const prefix = first ? "" : "    ";
      first = false;
      lines[lines.length - 1] += first ? "" : "";
      lines.push(prefix + key + ": " + value);
    }

    if (field !== "criteria") {
      lines.push("    criteria:");
      lines.push("      - id: test-criterion");
      lines.push('        label: "Test Criterion"');
      lines.push('        description: "A test criterion"');
    }

    // Remove the empty "  - " line and fix first field indent
    const result = lines
      .filter((l) => l.trim() !== "")
      .map((l, i) => {
        if (i === 1) return "  - " + l.trimStart();
        return l;
      });

    this.checkpointTemplateYaml = result.join("\n") + "\n";
  },
);
